INSERT OR REPLACE INTO model_params (model_id, schema_json, defaults_json) VALUES ('seedance-2-first-last-frame', '{"prompt":{"type":"string","maxLength":4000,"required":true,"title":"Prompt","description":"Text prompt describing the video (max 4000 characters)."},"images_list":{"type":"array","items":{"type":"string"},"required":true,"title":"Images List","description":"1 image = first frame only; 2 images = first and last frame."},"aspect_ratio":{"type":"string","options":["adaptive","21:9","16:9","4:3","1:1","3:4","9:16"],"default":"adaptive","title":"Aspect Ratio","description":"Output aspect ratio. ''adaptive'' matches the input frames (recommended for first/last-frame transitions). Concrete ratios may crop or pad."},"duration":{"type":"number","min":4,"max":15,"default":5,"title":"Duration"}}', '{"aspect_ratio":"adaptive","duration":5}');
