INSERT OR REPLACE INTO models (id, name, description, category, family, group_of, cost, cost_currency, dynamic_pricing, endpoint, estimate_endpoint, playground_url, llms_txt_url, is_active) VALUES ('seedance-2-vip-image-to-video', 'seedance-2-vip-image-to-video', 'Animate a still image with Seedance 2 VIP (premium tier). Input: prompt + images_list (1 = start frame; 2-9 = @image1…@image9). Output: high-quality video. Use for: production-grade image animation, multi-reference premium generation.', 'Image to Video', 'sd-2', 'video', 1.5, 'USD', 1, '/api/v1/seedance-2-vip-image-to-video', '/api/v1/models/seedance-2-vip-image-to-video/estimate-cost', 'https://muapi.ai/playground/seedance-2-vip-image-to-video', 'https://muapi.ai/playground/seedance-2-vip-image-to-video/llms.txt', 1);
INSERT OR REPLACE INTO model_params (model_id, schema_json, defaults_json) VALUES ('seedance-2-vip-image-to-video', '{"prompt":{"type":"string","maxLength":4000,"required":true,"title":"Prompt","description":"Text description guiding the video animation (max 4000 characters). To use a fictional character, reference it with @character:<id> (the request_id from a completed Seedance 2 Character generation) — the character image is automatically appended to images_list. Example: ''@character:ab539e5f walks along a city street at sunset''."},"images_list":{"type":"array","items":{"type":"string"},"required":true,"title":"Images List","description":"All image-to-video and reference-based requests use omni_reference mode. 1 image = start frame. 2–9 images = reference them in your prompt with @image1, @image2, etc."},"aspect_ratio":{"type":"string","options":["21:9","16:9","4:3","1:1","3:4","9:16"],"default":"16:9","title":"Aspect Ratio"},"duration":{"type":"number","min":4,"max":15,"default":5,"title":"Duration"}}', '{"aspect_ratio":"16:9","duration":5}');
