INSERT OR REPLACE INTO model_params (model_id, schema_json, defaults_json) VALUES ('seedance-2-vip-omni-reference', '{"prompt":{"type":"string","maxLength":4000,"required":true,"title":"Prompt","description":"Text prompt describing the video (max 4000 characters). Reference images with @image1…@image9, videos with @video1…@video3, and audio with @audio1…@audio3. To use a fictional character, reference it with @character:<request_id> (from a completed Seedance 2 Character generation). To use a trained Omni Reference character, reference it with @omni-character:<character_id>. Example: ''@image1 is the character. The person walks along a city street at sunset.''"},"images_list":{"type":"array","nullable":true,"title":"Images List","description":"Up to 9 reference images (JPEG/PNG/WebP). Referenced in prompt via @image1…@image9."},"video_files":{"type":"array","nullable":true,"title":"Video Files","description":"Up to 3 reference video clips (MP4, max 15s each). Referenced in prompt via @video1…@video3."},"audio_files":{"type":"array","nullable":true,"title":"Audio Files","description":"Up to 3 reference audio files (MP3/WAV, total max 15s). Referenced in prompt via @audio1…@audio3."},"aspect_ratio":{"type":"string","options":["21:9","16:9","4:3","1:1","3:4","9:16"],"default":"16:9","title":"Aspect Ratio"},"duration":{"type":"number","min":4,"max":15,"default":5,"title":"Duration"}}', '{"aspect_ratio":"16:9","duration":5}');
