INSERT OR REPLACE INTO models (id, name, description, category, family, group_of, cost, cost_currency, dynamic_pricing, endpoint, estimate_endpoint, playground_url, llms_txt_url, is_active) VALUES ('seedance-2-vip-extend', 'seedance-2-vip-extend', 'Extend a previously-generated Seedance 2 video by appending continued motion (SD-2 VIP, 720p output). Input: request_id of a completed Seedance 2 generation + optional prompt, reference images, video clips, audio clips (referenced in the prompt via @image2…@image9, @video1…@video3, @audio1…@audio3 — @image1 is automatically the source video''s last frame). Output: extended video. Use for: turning short clips into longer takes, continuing scenes; must be called after another Seedance 2 endpoint to', 'Video to Video', 'sd-v2.0', 'video', 1.05, 'USD', 1, '/api/v1/seedance-2-vip-extend', '/api/v1/models/seedance-2-vip-extend/estimate-cost', 'https://muapi.ai/playground/seedance-2-vip-extend', 'https://muapi.ai/playground/seedance-2-vip-extend/llms.txt', 1);
INSERT OR REPLACE INTO model_params (model_id, schema_json, defaults_json) VALUES ('seedance-2-vip-extend', '{"request_id":{"type":"string","required":true,"title":"Request Id"},"prompt":{"type":"string","nullable":true,"default":"","title":"Prompt","description":"Optional prompt to guide the extension. Reference additional images with @image2…@image9, videos with @video1…@video3, and audio with @audio1…@audio3 (the auto-extracted last frame of the source video is always @image1)."},"images_list":{"type":"array","nullable":true,"title":"Images List","description":"Up to 8 additional reference images. They map to @image2…@image9 in the prompt (@image1 is the source video''s last frame)."},"video_files":{"type":"array","nullable":true,"title":"Video Files","description":"Up to 3 reference video clips (MP4, max 15s each). Referenced in prompt via @video1…@video3."},"audio_files":{"type":"array","nullable":true,"title":"Audio Files","description":"Up to 3 reference audio files (MP3/WAV, total max 15s). Referenced in prompt via @audio1…@audio3."},"aspect_ratio":{"type":"string","options":["21:9","16:9","4:3","1:1","3:4","9:16"],"default":"16:9","title":"Aspect Ratio"},"quality":{"type":"string","options":["high","basic"],"default":"basic","title":"Quality"},"duration":{"type":"number","min":4,"max":15,"default":5,"title":"Duration"}}', '{"prompt":"","aspect_ratio":"16:9","quality":"basic","duration":5}');
